impl<T               , G: SpinGuardian> RwLockReadGuard<'_, T, G> {
    #[verus_spec]
    fn drop(self) {
        proof! {
            use_type_invariant(&self);
            use_type_invariant(self.inner);
            lemma_consts_properties();
        }
        proof_decl! {
            let tracked token = self.tracked_token.get();
        }
        atomic_with_ghost!(
            self.inner.lock => fetch_sub(READER);
            update prev -> next;
            ghost g => {
                lemma_consts_properties();
                lemma_consts_properties_value(prev as usize);
                lemma_consts_properties_prev_next(prev as usize, next as usize);
                token.bounded();
                match g.read_guard_token {
                    Sum::Left(_) => {
                        let tracked read_guard_token_ref = g.read_guard_token.tracked_borrow_left();
                        assert(read_guard_token_ref.id() == token.id());
                        let tracked mut read_guard_token = g.read_guard_token.tracked_take_left();
                        read_guard_token.combine(token);
                        g.read_guard_token = Sum::tracked_new_left(read_guard_token);
                    },
                    Sum::Right(_) => { }
                }
            }
        );
    }
}


